import React, { useEffect, useState } from "react";
import axios from "axios"; // Importa o Axios
import Product from "./Product"; // Importa o componente Product
import "./ProductList.scss";

const ProductList = () => {
  const [products, setProducts] = useState([]); // Estado para armazenar os produtos
  const [loading, setLoading] = useState(true); // Estado para indicar carregamento
  const [error, setError] = useState(null); // Estado para armazenar erros

  useEffect(() => {
    // Faz a requisição para o arquivo JSON usando Axios
    axios.get("/products.json") // Caminho para o arquivo JSON na pasta public
      .then((response) => {
        // Verifica se a resposta contém dados válidos
        if (Array.isArray(response.data)) {
          setProducts(response.data); // Atualiza o estado com os produtos
        } else {
          throw new Error("Dados inválidos: esperado um array de produtos");
        }
        setLoading(false); // Finaliza o carregamento
      })
      .catch((error) => {
        console.error("Erro ao carregar os produtos:", error);
        setError(error.message); // Armazena o erro
        setLoading(false); // Finaliza o carregamento
      });
  }, []); // O array vazio garante que o useEffect só rode uma vez

  if (loading) {
    return <div className="loading">Carregando...</div>; // Exibe mensagem de carregamento
  }

  if (error) {
    return <div className="error">Erro: {error}</div>; // Exibe mensagem de erro
  }

  return (
    <div className="product-list">
      {products.map((product) => (
        <Product key={product.productId} product={product} /> // Renderiza cada produto
      ))}
    </div>
  );
};

export default ProductList;
